insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('a4000000-0000-4000-8000-000000000001', 'a3000000-0000-4000-8000-000000000001', 'Sort & Pack Food in Richmond', 'food', 'Volunteers sort and pack donated groceries and help prepare meals at Feed More, which fights hunger across central Virginia. Shifts are a couple of hours and welcome individuals and groups. A hands-on way to help neighbors close to home.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://feedmore.org', 'https://feedmore.org', '2026-01-01T00:00:00Z', 'Richmond', 'VA'),
  ('a4000000-0000-4000-8000-000000000002', 'a3000000-0000-4000-8000-000000000002', 'Build Homes Across Virginia', 'community', 'Volunteers help build and repair affordable homes alongside future homeowners through Habitat for Humanity Virginia''s local affiliates. No construction experience is needed - site leaders teach you everything. A great option for groups.', array['good for crews', 'training provided'], 16, false, false, true, 'Half day', 'https://habitatvirginia.org', 'https://habitatvirginia.org', '2026-01-01T00:00:00Z', 'Richmond', 'VA'),
  ('a4000000-0000-4000-8000-000000000003', 'a3000000-0000-4000-8000-000000000003', 'Care for Shelter Animals', 'animals', 'Volunteers walk dogs, socialize cats, and help at adoption events at the Richmond SPCA, a national no-kill leader. Orientation and training are provided. A rewarding role for animal lovers of all kinds.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://richmondspca.org', 'https://richmondspca.org', '2026-01-01T00:00:00Z', 'Richmond', 'VA'),
  ('a4000000-0000-4000-8000-000000000004', 'a3000000-0000-4000-8000-000000000004', 'Pack Food for the Valley', 'food', 'Volunteers sort and box donated food at the Blue Ridge Area Food Bank for distribution across western Virginia. Shifts fit many schedules and welcome groups. A friendly way to help neighbors facing hunger.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://brafb.org', 'https://brafb.org', '2026-01-01T00:00:00Z', 'Verona', 'VA'),
  ('a4000000-0000-4000-8000-000000000005', 'a3000000-0000-4000-8000-000000000005', 'Volunteer in Greater Richmond', 'community', 'Volunteers support education, financial-stability, and health programs through United Way of Greater Richmond & Petersburg, from reading with kids to community events. There are roles for many interests. Check the site for current opportunities.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://yourunitedway.org', 'https://yourunitedway.org', '2026-01-01T00:00:00Z', 'Richmond', 'VA'),
  ('a4000000-0000-4000-8000-000000000006', 'a3000000-0000-4000-8000-000000000006', 'Sort Food in Birmingham', 'food', 'Volunteers sort and box donated groceries at the Community Food Bank of Central Alabama for distribution to partner pantries. Shifts are welcoming to individuals, families, and groups. A great way to fight hunger in central Alabama.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://feedingal.org', 'https://feedingal.org', '2026-01-01T00:00:00Z', 'Birmingham', 'AL'),
  ('a4000000-0000-4000-8000-000000000007', 'a3000000-0000-4000-8000-000000000007', 'Build with Habitat Birmingham', 'community', 'Volunteers frame, paint, and landscape affordable homes alongside partner families with Habitat for Humanity of Greater Birmingham. No experience is needed, and the ReStore also welcomes helpers. A rewarding day for groups.', array['good for crews', 'training provided'], 16, false, false, true, 'Half day', 'https://habitatbirmingham.org', 'https://habitatbirmingham.org', '2026-01-01T00:00:00Z', 'Birmingham', 'AL'),
  ('a4000000-0000-4000-8000-000000000008', 'a3000000-0000-4000-8000-000000000008', 'Help at the Humane Society', 'animals', 'Volunteers care for animals, help at adoption events, and support programs at the Greater Birmingham Humane Society. Orientation is provided, and there are roles for many schedules. A great fit for animal lovers.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://gbhs.org', 'https://gbhs.org', '2026-01-01T00:00:00Z', 'Birmingham', 'AL'),
  ('a4000000-0000-4000-8000-000000000009', 'a3000000-0000-4000-8000-000000000009', 'Steward Ruffner Mountain', 'environment', 'Volunteers maintain trails, remove invasive plants, and help at events at Ruffner Mountain, a nature preserve in the heart of Birmingham. It is satisfying outdoor work and a great way to earn hours. Groups are welcome on workdays.', array['outdoors', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://ruffnermountain.org', 'https://ruffnermountain.org', '2026-01-01T00:00:00Z', 'Birmingham', 'AL'),
  ('a4000000-0000-4000-8000-000000000010', 'a3000000-0000-4000-8000-000000000010', 'Volunteer with United Way', 'community', 'Volunteers support education, health, and financial-stability programs through United Way of Central Alabama, from tutoring to community projects. There are roles for many interests and schedules. See the site for current openings.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://uwca.org', 'https://uwca.org', '2026-01-01T00:00:00Z', 'Birmingham', 'AL'),
  ('a4000000-0000-4000-8000-000000000011', 'a3000000-0000-4000-8000-000000000011', 'Sort Food in Anchorage', 'food', 'Volunteers sort and repack donated food at the Food Bank of Alaska for distribution to pantries across the state. Shifts are a couple of hours and welcome groups. A meaningful way to fight hunger in Alaska.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://foodbankofalaska.org', 'https://foodbankofalaska.org', '2026-01-01T00:00:00Z', 'Anchorage', 'AK'),
  ('a4000000-0000-4000-8000-000000000012', 'a3000000-0000-4000-8000-000000000012', 'Volunteer at the Alaska Zoo', 'animals', 'Volunteers help with education programs, events, and guest experience at The Alaska Zoo, home to northern and arctic animals. Training is provided, and it is a fun fit if you love wildlife. Roles suit many schedules.', array['recurring', 'family friendly'], 16, false, false, true, '2-4 hrs', 'https://www.alaskazoo.org', 'https://www.alaskazoo.org', '2026-01-01T00:00:00Z', 'Anchorage', 'AK'),
  ('a4000000-0000-4000-8000-000000000013', 'a3000000-0000-4000-8000-000000000013', 'Tend the Botanical Garden', 'gardening', 'Volunteers weed, plant, and maintain the collections at the Alaska Botanical Garden, a 110-acre sub-arctic garden in Anchorage. It is hands-on outdoor work for garden lovers. Community workdays welcome groups.', array['outdoors', 'physical work', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://www.alaskabg.org', 'https://www.alaskabg.org', '2026-01-01T00:00:00Z', 'Anchorage', 'AK'),
  ('a4000000-0000-4000-8000-000000000014', 'a3000000-0000-4000-8000-000000000014', 'Serve Meals at Bean''s Cafe', 'food', 'Volunteers help prepare and serve meals and support guests at Bean''s Cafe, an Anchorage nonprofit serving people facing hunger and homelessness. Shifts are welcoming and a great way to help neighbors directly. Groups are welcome.', array['good for crews', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://beanscafe.org', 'https://beanscafe.org', '2026-01-01T00:00:00Z', 'Anchorage', 'AK'),
  ('a4000000-0000-4000-8000-000000000015', 'a3000000-0000-4000-8000-000000000015', 'Care for Anchorage Parks', 'environment', 'Volunteers join workdays to plant, clean, and care for trails and parks with the Anchorage Park Foundation. It is satisfying outdoor work that keeps the city green. Great for individuals and crews.', array['outdoors', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://anchorageparkfoundation.org', 'https://anchorageparkfoundation.org', '2026-01-01T00:00:00Z', 'Anchorage', 'AK'),
  ('a4000000-0000-4000-8000-000000000016', 'a3000000-0000-4000-8000-000000000016', 'Sort Food in Little Rock', 'food', 'Volunteers sort and box donated groceries at the Arkansas Foodbank for distribution across 33 counties. Shifts are a couple of hours and welcome groups. A friendly, hands-on way to fight hunger.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://arkansasfoodbank.org', 'https://arkansasfoodbank.org', '2026-01-01T00:00:00Z', 'Little Rock', 'AR'),
  ('a4000000-0000-4000-8000-000000000017', 'a3000000-0000-4000-8000-000000000017', 'Build with Habitat Central AR', 'community', 'Volunteers help build affordable homes or lend a hand at the ReStore with Habitat for Humanity of Central Arkansas. No experience is needed, and site leaders teach you everything. A rewarding day for groups.', array['good for crews', 'training provided'], 16, false, false, true, 'Half day', 'https://habitatcentralar.org', 'https://habitatcentralar.org', '2026-01-01T00:00:00Z', 'Little Rock', 'AR'),
  ('a4000000-0000-4000-8000-000000000018', 'a3000000-0000-4000-8000-000000000018', 'Volunteer at the Little Rock Zoo', 'animals', 'Volunteers and docents help with education, guest experience, and conservation programs at the Little Rock Zoo, Arkansas''s largest. Training is provided, and it is a fun fit if you love animals. Roles suit many schedules.', array['recurring', 'family friendly'], 16, false, false, true, '2-4 hrs', 'https://www.littlerockzoo.com', 'https://www.littlerockzoo.com', '2026-01-01T00:00:00Z', 'Little Rock', 'AR'),
  ('a4000000-0000-4000-8000-000000000019', 'a3000000-0000-4000-8000-000000000019', 'Help at a No-Kill Shelter', 'animals', 'Volunteers walk dogs, care for cats, and help with adoptions at the no-kill Humane Society of Pulaski County in Little Rock. An application and orientation get you started. A rewarding role for animal lovers.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://warmhearts.org', 'https://warmhearts.org', '2026-01-01T00:00:00Z', 'Little Rock', 'AR'),
  ('a4000000-0000-4000-8000-000000000020', 'a3000000-0000-4000-8000-000000000020', 'Support Families at Our House', 'community', 'Volunteers tutor children, help in the career center, and support programs at Our House, a Little Rock nonprofit empowering working homeless families. There are roles for many skills. A meaningful way to help families thrive.', array['recurring', 'counts for school hours'], 16, false, false, true, '2-3 hrs', 'https://www.ourhouseshelter.org', 'https://www.ourhouseshelter.org', '2026-01-01T00:00:00Z', 'Little Rock', 'AR'),
