  ('a4000000-0000-4000-8000-000000000025', 'a3000000-0000-4000-8000-000000000025', 'Volunteer with United Way CT', 'community', 'Volunteers support education, income, and health programs through United Way of Central and Northeastern Connecticut, from tutoring to community events. There are roles for many interests. See the site for openings.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://www.unitedwayinc.org', 'https://www.unitedwayinc.org', '2026-01-01T00:00:00Z', 'Hartford', 'CT'),
  ('a4000000-0000-4000-8000-000000000026', 'a3000000-0000-4000-8000-000000000026', 'Sort Food in Delaware', 'food', 'Volunteers sort and pack donated food at the Food Bank of Delaware in Newark for distribution across the state. Shifts are a couple of hours and welcome groups. A friendly way to help feed Delawareans.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://www.fbd.org', 'https://www.fbd.org', '2026-01-01T00:00:00Z', 'Newark', 'DE'),
  ('a4000000-0000-4000-8000-000000000027', 'a3000000-0000-4000-8000-000000000027', 'Build with Habitat NCC', 'community', 'Volunteers help build affordable homes or lend a hand at the ReStore with Habitat for Humanity of New Castle County. No experience is needed, and groups are welcome. A rewarding, hands-on day.', array['good for crews', 'training provided'], 16, false, false, true, 'Half day', 'https://www.habitatncc.org', 'https://www.habitatncc.org', '2026-01-01T00:00:00Z', 'Wilmington', 'DE'),
  ('a4000000-0000-4000-8000-000000000028', 'a3000000-0000-4000-8000-000000000028', 'Help Shelter Animals in DE', 'animals', 'Volunteers care for animals, help with adoptions, and support events with the Brandywine Valley SPCA in Delaware. Orientation is provided, and there are roles for many schedules. A great fit for animal lovers.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://bvspca.org', 'https://bvspca.org', '2026-01-01T00:00:00Z', 'Wilmington', 'DE'),
  ('a4000000-0000-4000-8000-000000000029', 'a3000000-0000-4000-8000-000000000029', 'Steward Delaware Nature', 'environment', 'Volunteers help maintain preserves, lead programs, and care for the outdoors with the Delaware Nature Society. It is satisfying outdoor work for nature lovers. Great for individuals and crews.', array['outdoors', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.delnature.org', 'https://www.delnature.org', '2026-01-01T00:00:00Z', 'Hockessin', 'DE'),
  ('a4000000-0000-4000-8000-000000000030', 'a3000000-0000-4000-8000-000000000030', 'Volunteer with United Way DE', 'community', 'Volunteers support education, income, and health programs through United Way of Delaware, from reading with kids to community projects. There are roles for many interests and schedules. See the site for current openings.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://www.uwde.org', 'https://www.uwde.org', '2026-01-01T00:00:00Z', 'Wilmington', 'DE')
